    public static function folderType(string $path,string $flags=''): string
    {
        $value=mb_strtolower($path.' '.$flags,'UTF-8');
        foreach(['inbox'=>['inbox','دریافتی'],'sent'=>['sent','ارسال'],'drafts'=>['draft','پیش‌نویس'],'spam'=>['spam','junk','هرز'],'trash'=>['trash','deleted','حذف'],'archive'=>['archive','all mail','آرشیو']] as $type=>$needles)foreach($needles as $needle)if(str_contains($value,$needle))return $type;
        return 'custom';
    }

    private static function date(?string $value): ?string
    {
        if(!$value)return null;try{return (new DateTimeImmutable($value))->format('Y-m-d H:i:s');}catch(Throwable){return null;}
    }
    private static function snippet(string $text): string{$text=trim(preg_replace('/\s+/u',' ',strip_tags($text))??'');return mb_substr($text,0,500);}
    private static function attachmentPath(int $accountId,string $name): array
