        $extension=strtolower(pathinfo($name,PATHINFO_EXTENSION));$extension=preg_match('/^[a-z0-9]{1,10}$/',$extension)?'.'.$extension:'';$root=dirname(__DIR__);$dir=$root.'/uploads/email/account_'.$accountId;if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('email_attachment_directory_failed');$stored=bin2hex(random_bytes(20)).$extension;return [$dir.'/'.$stored,'/uploads/email/account_'.$accountId.'/'.$stored,$stored];
    }
    private static function saveAttachment(int $accountId,int $messageId,array $attachment): void
    {
