        Database::execute('INSERT INTO email_attachments(message_id,account_id,file_name,mime_type,file_size,storage_path,content_id,is_inline,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())',[$messageId,$accountId,mb_substr((string)$attachment['name'],0,255),mb_substr((string)$attachment['mime'],0,190),strlen((string)$attachment['data']),$relative,mb_substr((string)$attachment['content_id'],0,500),(int)$attachment['inline']]);
    }
    private static function headerAddress(array $headers,string $key): array{return EmailMimeParser::addresses($headers[$key]??'');}
    private static function saveMessage(array $account,array $folder,int $uid,array $fetched): ?int
    {
        $mime=EmailMimeParser::parse($fetched['raw']);$h=$mime['headers'];$from=self::headerAddress($h,'from')[0]??['name'=>'','email'=>''];$html=EmailHubModule::sanitizeHtml($mime['html']);$text=(string)$mime['text'];$status=$folder['folder_type']==='spam'?'spam':($folder['folder_type']==='trash'?'deleted':'new');$read=str_contains($fetched['flags'],'\\Seen')?1:0;if($read&&$status==='new')$status='read';$messageId=trim((string)($h['message-id']??''),'<> ');
        Database::execute('INSERT IGNORE INTO email_messages(account_id,folder_id,uid_validity,remote_uid,message_id,thread_id,subject,from_email,from_name,to_json,cc_json,bcc_json,reply_to_json,date_received,date_sent,body_text,body_html,snippet,has_attachments,is_read,is_starred,is_flagged,is_answered,importance,status,tags_json,raw_headers_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())',[
            (int)$account['id'],(int)$folder['id'],(int)$folder['uid_validity'],$uid,mb_substr($messageId,0,500),mb_substr(trim((string)($h['references']??$messageId),'<> '),0,500),mb_substr(EmailMimeParser::decodeHeader($h['subject']??'بدون موضوع'),0,500),mb_substr($from['email'],0,255),mb_substr($from['name'],0,255),json_encode(self::headerAddress($h,'to'),JSON_UNESCAPED_UNICODE),json_encode(self::headerAddress($h,'cc'),JSON_UNESCAPED_UNICODE),json_encode(self::headerAddress($h,'bcc'),JSON_UNESCAPED_UNICODE),json_encode(self::headerAddress($h,'reply-to'),JSON_UNESCAPED_UNICODE),self::date($h['date']??null),self::date($h['date']??null),$text,$html,self::snippet($text!==''?$text:$html),$mime['attachments']?1:0,$read,str_contains($fetched['flags'],'\\Flagged')?1:0,str_contains($fetched['flags'],'\\Flagged')?1:0,str_contains($fetched['flags'],'\\Answered')?1:0,stripos((string)($h['importance']??''),'high')!==false?'high':'normal',$status,null,json_encode($h,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)
        ]);
        $row=Database::fetch('SELECT id FROM email_messages WHERE account_id=? AND folder_id=? AND uid_validity=? AND remote_uid=?',[(int)$account['id'],(int)$folder['id'],(int)$folder['uid_validity'],$uid]);if(!$row)return null;$id=(int)$row['id'];
        if(!Database::fetch('SELECT id FROM email_attachments WHERE message_id=? LIMIT 1',[$id]))foreach($mime['attachments'] as $attachment)self::saveAttachment((int)$account['id'],$id,$attachment);
