    }
    public static function syncAccount(int $accountId,int $limitPerFolder=100): array
    {
        $account=EmailHubModule::account($accountId);if(!$account||!(int)$account['active']||!(int)$account['sync_enabled'])throw new RuntimeException('email_account_sync_disabled');if(!$account['imap_host'])throw new RuntimeException('imap_host_missing');
        Database::execute("UPDATE email_accounts SET sync_status='syncing',last_error=NULL,updated_at=NOW() WHERE id=?",[$accountId]);EmailHubModule::log($accountId,null,'sync_started','همگام‌سازی حساب آغاز شد.');$count=0;
        try{$client=new EmailImapClient($account);$remoteFolders=$client->folders();foreach($remoteFolders as $index=>$remote){$type=self::folderType($remote['path'],$remote['flags']);Database::execute('INSERT INTO email_folders(account_id,remote_folder_id,folder_name,folder_path,folder_type,sync_enabled,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,1,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE remote_folder_id=VALUES(remote_folder_id),folder_name=VALUES(folder_name),folder_type=VALUES(folder_type),sort_order=VALUES(sort_order),updated_at=NOW()',[$accountId,$remote['remote_path'],basename(str_replace('\\','/',$remote['path'])),$remote['path'],$type,$index*10]);$folder=Database::fetch('SELECT * FROM email_folders WHERE account_id=? AND folder_path=?',[$accountId,$remote['path']]);if(!$folder||(int)$folder['sync_enabled']!==1)continue;$selected=$client->select((string)$remote['remote_path']);$uidValidity=(int)$selected['uid_validity'];$last=((int)$folder['uid_validity']===$uidValidity)?(int)$folder['last_uid']:0;$uids=array_slice($client->searchAfter($last),0,max(1,min(500,$limitPerFolder)));$maxUid=$last;$folder['uid_validity']=$uidValidity;foreach($uids as $uid){if($uid<=0)continue;self::saveMessage($account,$folder,$uid,$client->fetch($uid));$maxUid=max($maxUid,$uid);$count++;}Database::execute('UPDATE email_folders SET total_messages=?,unread_count=(SELECT COUNT(*) FROM email_messages WHERE folder_id=? AND is_read=0 AND status<>"deleted"),uid_validity=?,last_uid=?,updated_at=NOW() WHERE id=?',[(int)$selected['exists'],(int)$folder['id'],$uidValidity,$maxUid,(int)$folder['id']]);}$client->close();Database::execute("UPDATE email_accounts SET sync_status='ok',last_sync_at=NOW(),last_error=NULL,updated_at=NOW() WHERE id=?",[$accountId]);EmailHubModule::log($accountId,null,'sync_completed','همگام‌سازی حساب تکمیل شد.',null,['new_messages'=>$count]);return ['ok'=>true,'count'=>$count];}
        catch(Throwable $e){Database::execute("UPDATE email_accounts SET sync_status='error',last_error=?,updated_at=NOW() WHERE id=?",[mb_substr($e->getMessage(),0,1000),$accountId]);EmailHubModule::log($accountId,null,'sync_failed','همگام‌سازی حساب ناموفق بود.',$e->getMessage());throw $e;}
    }
    public static function syncEnabled(int $limitAccounts=20): array{$rows=Database::fetchAll('SELECT id FROM email_accounts WHERE active=1 AND sync_enabled=1 ORDER BY COALESCE(last_sync_at,"1970-01-01") LIMIT '.max(1,min(100,$limitAccounts)));$result=[];foreach($rows as $row){try{$result[(int)$row['id']]=self::syncAccount((int)$row['id']);}catch(Throwable $e){$result[(int)$row['id']]=['ok'=>false];}}foreach(Database::fetchAll("SELECT id FROM email_messages WHERE status IN ('new','read','pending_reply') ORDER BY id DESC LIMIT 500") as $message)self::applyRules((int)$message['id']);return $result;}
    private static function condition(array $message,array $rule): bool
    {
        $field=match($rule['condition_field']){'from'=>(string)$message['from_email'],'subject'=>(string)$message['subject'],'body'=>(string)$message['body_text'],'has_attachment'=>(string)(int)$message['has_attachments'],'age_hours'=>(string)floor((time()-strtotime($message['date_received']?:$message['created_at']))/3600),default=>''};$wanted=(string)$rule['condition_value'];return match($rule['condition_operator']){'equals'=>mb_strtolower($field)===mb_strtolower($wanted),'domain'=>str_ends_with(mb_strtolower($field),'@'.ltrim(mb_strtolower($wanted),'@')),'greater_than'=>(float)$field>(float)$wanted,default=>mb_stripos($field,$wanted)!==false};
    }
    public static function applyRules(int $messageId): void
    {
        $message=Database::fetch('SELECT * FROM email_messages WHERE id=?',[$messageId]);if(!$message)return;$rules=Database::fetchAll('SELECT * FROM email_rules WHERE active=1 AND (account_id IS NULL OR account_id=?) ORDER BY priority,id',[(int)$message['account_id']]);foreach($rules as $rule){if(!self::condition($message,$rule))continue;switch($rule['action_type']){case'add_tag':$tags=json_decode($message['tags_json']?:'[]',true)?:[];$tags[]=trim((string)$rule['action_value']);$tags=array_values(array_unique(array_filter($tags)));Database::execute('UPDATE email_messages SET tags_json=? WHERE id=?',[json_encode($tags,JSON_UNESCAPED_UNICODE),$messageId]);break;case'assign_user':Database::execute('UPDATE email_messages SET assigned_user_id=? WHERE id=?',[(int)$rule['action_value']?:null,$messageId]);break;case'assign_group':Database::execute('UPDATE email_messages SET assigned_group=? WHERE id=?',[mb_substr((string)$rule['action_value'],0,190),$messageId]);break;case'set_pending_reply':Database::execute("UPDATE email_messages SET status='pending_reply' WHERE id=?",[$messageId]);break;case'mark_important':Database::execute("UPDATE email_messages SET importance='high',is_flagged=1 WHERE id=?",[$messageId]);break;case'create_ticket':self::queueIntegration($messageId,'ticket');break;}}
    }
    public static function queueIntegration(int $messageId,string $type='ticket',?int $userId=null): int
    {
        $type=$type==='cartable'?'cartable':'ticket';Database::execute('INSERT INTO email_integrations(message_id,integration_type,status,requested_by,payload_json,created_at,updated_at) VALUES(?,?,"pending",?,?,NOW(),NOW())',[$messageId,$type,$userId?:((int)(Auth::user()['id']??0)?:null),json_encode(['source'=>'email_hub'],JSON_UNESCAPED_UNICODE)]);return (int)Database::lastInsertId();
    }
    public static function moveMessage(int $messageId,string $destination): void
    {
        $message=Database::fetch('SELECT m.*,f.remote_folder_id source_remote,a.* FROM email_messages m JOIN email_folders f ON f.id=m.folder_id JOIN email_accounts a ON a.id=m.account_id WHERE m.id=?',[$messageId]);if(!$message)throw new RuntimeException('email_message_missing');$type=$destination==='archive'?'archive':($destination==='spam'?'spam':'trash');$target=Database::fetch('SELECT * FROM email_folders WHERE account_id=? AND folder_type=? ORDER BY id LIMIT 1',[(int)$message['account_id'],$type]);if($target&&!str_starts_with((string)$message['source_remote'],'local-')){try{$account=EmailHubModule::account((int)$message['account_id']);$client=new EmailImapClient($account);$client->connect();$client->select((string)$message['source_remote']);$client->move((int)$message['remote_uid'],(string)$target['remote_folder_id']);$client->close();}catch(Throwable $e){EmailHubModule::log((int)$message['account_id'],$messageId,'remote_move_failed','جابجایی راه‌دور ایمیل انجام نشد.',$e->getMessage());}}
        Database::execute('UPDATE email_messages SET folder_id=COALESCE(?,folder_id),status=?,updated_at=NOW() WHERE id=?',[$target['id']??null,$type==='archive'?'archived':($type==='spam'?'spam':'deleted'),$messageId]);EmailHubModule::log((int)$message['account_id'],$messageId,$type==='archive'?'message_archived':'message_deleted',$type==='archive'?'ایمیل آرشیو شد.':'ایمیل به حذف‌شده‌ها منتقل شد.');
    }
    public static function markRead(int $messageId): void
    {
        $message=Database::fetch('SELECT m.*,f.remote_folder_id,a.* FROM email_messages m JOIN email_folders f ON f.id=m.folder_id JOIN email_accounts a ON a.id=m.account_id WHERE m.id=?',[$messageId]);if(!$message||$message['is_read'])return;Database::execute("UPDATE email_messages SET is_read=1,status=IF(status='new','read',status),updated_at=NOW() WHERE id=?",[$messageId]);try{if(!str_starts_with((string)$message['remote_folder_id'],'local-')){$account=EmailHubModule::account((int)$message['account_id']);$client=new EmailImapClient($account);$client->connect();$client->select((string)$message['remote_folder_id']);$client->markSeen((int)$message['remote_uid']);$client->close();}}catch(Throwable $e){EmailHubModule::log((int)$message['account_id'],$messageId,'remote_seen_failed','وضعیت خواندن راه‌دور به‌روزرسانی نشد.',$e->getMessage());}EmailHubModule::log((int)$message['account_id'],$messageId,'message_read','ایمیل خوانده شد.');
    }
    public static function processOutbox(int $limit=20,?int $onlyId=null): array
    {
        $where="status='queued' AND (scheduled_at IS NULL OR scheduled_at<=NOW())";$params=[];if($onlyId){$where.=' AND id=?';$params[]=$onlyId;}$rows=Database::fetchAll("SELECT * FROM email_outbox WHERE {$where} ORDER BY id LIMIT ".max(1,min(100,$limit)),$params);$sent=0;$failed=0;foreach($rows as $outbox){$id=(int)$outbox['id'];Database::execute("UPDATE email_outbox SET status='sending',attempts=attempts+1,updated_at=NOW() WHERE id=? AND status='queued'",[$id]);try{$account=EmailHubModule::account((int)$outbox['account_id']);if(!$account||!(int)$account['send_enabled'])throw new RuntimeException('smtp_send_disabled');$attachments=Database::fetchAll('SELECT * FROM email_attachments WHERE outbox_id=?',[$id]);$mail=['to'=>json_decode($outbox['to_json'],true)?:[],'cc'=>json_decode($outbox['cc_json']?:'[]',true)?:[],'bcc'=>json_decode($outbox['bcc_json']?:'[]',true)?:[],'subject'=>$outbox['subject'],'body_html'=>$outbox['body_html'],'body_text'=>$outbox['body_text']];if($outbox['related_message_id']){$related=Database::fetch('SELECT message_id FROM email_messages WHERE id=?',[(int)$outbox['related_message_id']]);$mail['in_reply_to']=$related['message_id']??null;}$remoteId=(new EmailSmtpClient($account))->send($mail,$attachments);Database::execute("UPDATE email_outbox SET status='sent',sent_at=NOW(),last_error=NULL,updated_at=NOW() WHERE id=?",[$id]);self::storeSent($outbox,$account,$remoteId);if($outbox['related_message_id'])Database::execute("UPDATE email_messages SET status=?,is_answered=?,is_forwarded=?,updated_at=NOW() WHERE id=?",[$outbox['send_type']==='forward'?'forwarded':'replied',$outbox['send_type']==='forward'?0:1,$outbox['send_type']==='forward'?1:0,(int)$outbox['related_message_id']]);EmailHubModule::log((int)$account['id'],$outbox['related_message_id']?(int)$outbox['related_message_id']:null,$outbox['send_type']==='forward'?'message_forwarded':($outbox['send_type']==='compose'?'message_sent':'message_replied'),'ایمیل با موفقیت ارسال شد.');$sent++;}catch(Throwable $e){Database::execute("UPDATE email_outbox SET status=IF(attempts<3,'queued','failed'),last_error=?,updated_at=NOW() WHERE id=?",[mb_substr($e->getMessage(),0,1000),$id]);EmailHubModule::log((int)$outbox['account_id'],$outbox['related_message_id']?(int)$outbox['related_message_id']:null,'send_failed','ارسال ایمیل ناموفق بود.',$e->getMessage());$failed++;}}return ['sent'=>$sent,'failed'=>$failed];
    }
