        Database::execute('INSERT INTO email_folders(account_id,remote_folder_id,folder_name,folder_path,folder_type,sync_enabled,sort_order,created_at,updated_at) VALUES(?,"local-sent","ارسال‌شده‌ها","local-sent","sent",0,20,NOW(),NOW()) ON DUPLICATE KEY UPDATE folder_type="sent"',[(int)$account['id']]);$folder=Database::fetch('SELECT id FROM email_folders WHERE account_id=? AND folder_path="local-sent"',[(int)$account['id']]);if(!$folder)return;$has=Database::fetch('SELECT id FROM email_attachments WHERE outbox_id=? LIMIT 1',[(int)$outbox['id']])?1:0;$existing=Database::fetch('SELECT id FROM email_messages WHERE outbox_id=?',[(int)$outbox['id']]);if($existing)Database::execute('UPDATE email_messages SET folder_id=?,remote_uid=?,message_id=?,subject=?,to_json=?,cc_json=?,bcc_json=?,date_received=NOW(),date_sent=NOW(),body_text=?,body_html=?,snippet=?,has_attachments=?,status="read",updated_at=NOW() WHERE id=?',[(int)$folder['id'],8000000000000000000+(int)$outbox['id'],trim($remoteId,'<>'),$outbox['subject'],$outbox['to_json'],$outbox['cc_json'],$outbox['bcc_json'],$outbox['body_text'],$outbox['body_html'],self::snippet((string)($outbox['body_text']?:strip_tags($outbox['body_html']))),$has,(int)$existing['id']]);else Database::execute('INSERT IGNORE INTO email_messages(account_id,folder_id,uid_validity,remote_uid,outbox_id,message_id,subject,from_email,from_name,to_json,cc_json,bcc_json,date_received,date_sent,body_text,body_html,snippet,has_attachments,is_read,status,created_at,updated_at) VALUES(?,?,0,?,?,?,?,?,?,?,?,?,NOW(),NOW(),?,?,?,?,1,"read",NOW(),NOW())',[(int)$account['id'],(int)$folder['id'],8000000000000000000+(int)$outbox['id'],(int)$outbox['id'],trim($remoteId,'<>'),$outbox['subject'],$account['email_address'],$account['display_name'],$outbox['to_json'],$outbox['cc_json'],$outbox['bcc_json'],$outbox['body_text'],$outbox['body_html'],self::snippet((string)($outbox['body_text']?:strip_tags($outbox['body_html']))),$has]);
